import {
  PlaneGeometry,
  MeshBasicNodeMaterial,
  Mesh,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // --- setup geometry ---
  const aspect = 512 / 320; // from atlas source rect
  const width = 2.5;        // reasonable card width in scene units
  const height = width / aspect;
  const geometry = new PlaneGeometry(width, height);

  // --- material with placeholder color (surface near-black) ---
  const material = new MeshBasicNodeMaterial({
    color: 0x0b0b10, // surface
    transparent: false,
  });

  // --- mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.name = 'pricing-card-3';

  // --- texture loading ---
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    }).catch(() => {
      // fail silently, keep placeholder color
    });
  }

  // --- handlers (none) ---
  mesh.userData.handlers = {};

  // --- cleanup ---
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
  };

  return mesh;
}
